-- Allow the generic restore successor marker on app_connection_sessions records.
ALTER TABLE app_connection_sessions DROP CONSTRAINT app_connection_sessions_record_identity;
ALTER TABLE app_connection_sessions ADD CONSTRAINT app_connection_sessions_record_identity CHECK (
CASE
    WHEN record ? 'credential_repair'::text THEN (deft_app_connection_credential_repair_record_valid(record) AND (record ->> 'session_id'::text) = session_id AND ((record ->> 'revision'::text)::integer) = revision AND ((record -> 'scope'::text) ->> 'org_id'::text) = org_id AND ((record -> 'scope'::text) ->> 'owner_user_id'::text) = owner_user_id AND (NOT record ? 'restore'::text OR (jsonb_typeof(record -> 'restore'::text) = 'object'::text AND (record -> 'restore'::text) ?& ARRAY['schema_version'::text, 'source'::text] AND ((record -> 'restore'::text) - ARRAY['schema_version'::text, 'source'::text]) = '{}'::jsonb AND (record -> 'restore'::text ->> 'schema_version'::text) = 'deft.app_connection_restore.v1' AND jsonb_typeof((record -> 'restore'::text) -> 'source'::text) = 'object'::text AND ((record -> 'restore'::text) -> 'source'::text) ?& ARRAY['session_id'::text] AND (((record -> 'restore'::text) -> 'source'::text) - ARRAY['session_id'::text]) = '{}'::jsonb AND (((record -> 'restore'::text) -> 'source'::text) ->> 'session_id'::text) ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'::text AND (((record -> 'restore'::text) -> 'source'::text) ->> 'session_id'::text) <> session_id))) IS TRUE
    ELSE (jsonb_typeof(record) = 'object'::text AND record ?& ARRAY['session_id'::text, 'revision'::text, 'scope'::text, 'profile'::text, 'state'::text, 'callback_state_hash'::text, 'callback_consumed'::text, 'callback_expires_at'::text, 'runtime_session_ref'::text, 'account'::text, 'created_at'::text, 'updated_at'::text] AND (record - ARRAY['session_id'::text, 'revision'::text, 'scope'::text, 'profile'::text, 'state'::text, 'callback_state_hash'::text, 'callback_consumed'::text, 'callback_expires_at'::text, 'runtime_session_ref'::text, 'account'::text, 'created_at'::text, 'updated_at'::text, 'action_consent'::text, 'reattachment'::text, 'action_consents'::text, 'upgrade'::text, 'restore'::text]) = '{}'::jsonb AND jsonb_typeof(record -> 'scope'::text) = 'object'::text AND jsonb_typeof(record -> 'profile'::text) = 'object'::text AND (record -> 'scope'::text) ?& ARRAY['org_id'::text, 'owner_user_id'::text] AND (record ->> 'session_id'::text) = session_id AND ((record ->> 'revision'::text)::integer) = revision AND ((record -> 'scope'::text) ->> 'org_id'::text) = org_id AND ((record -> 'scope'::text) ->> 'owner_user_id'::text) = owner_user_id AND (record ->> 'callback_state_hash'::text) ~ '^[a-f0-9]{64}$'::text AND jsonb_typeof(record -> 'callback_consumed'::text) = 'boolean'::text AND (NOT record ? 'action_consent'::text OR jsonb_typeof(record -> 'action_consent'::text) = 'object'::text AND (record -> 'action_consent'::text) ?& ARRAY['action_binding_id'::text, 'action_key'::text, 'authority_epoch'::text, 'consent_id'::text, 'consent_digest'::text, 'expires_at'::text] AND ((record -> 'action_consent'::text) - ARRAY['consent_lifetime'::text, 'action_binding_id'::text, 'action_key'::text, 'authority_epoch'::text, 'consent_id'::text, 'consent_digest'::text, 'expires_at'::text]) = '{}'::jsonb AND ((record -> 'action_consent'::text) ->> 'action_binding_id'::text) ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'::text AND ((record -> 'action_consent'::text) ->> 'consent_id'::text) = ((record -> 'action_consent'::text) ->> 'action_binding_id'::text) AND ((record -> 'action_consent'::text) ->> 'action_key'::text) ~ '^[a-z][a-z0-9_]{0,47}$'::text AND jsonb_typeof((record -> 'action_consent'::text) -> 'authority_epoch'::text) = 'number'::text AND (((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) >= 0::numeric AND (((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) <= 2147483647::numeric AND (((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) = trunc(((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) AND ((record -> 'action_consent'::text) ->> 'consent_digest'::text) ~ '^sha256:[a-f0-9]{64}$'::text AND deft_app_consent_valid(record -> 'action_consent'::text,'expires_at') AND deft_app_consent_deadline(record -> 'action_consent'::text,'expires_at') <= deft_app_consent_deadline(record -> 'scope'::text)) AND (((record ->> 'state'::text) = ANY (ARRAY['starting'::text, 'awaiting_callback'::text, 'connecting'::text, 'checking'::text, 'disconnecting'::text, 'connected'::text, 'not_connected'::text, 'disconnected'::text, 'indeterminate'::text])) OR record ? 'reattachment'::text AND ((record ->> 'state'::text) = ANY (ARRAY['reattach_reviewed'::text, 'reattaching'::text, 'reattach_checking'::text])) OR record ? 'upgrade'::text AND ((record ->> 'state'::text) = ANY (ARRAY['upgrade_reviewed'::text, 'upgrade_starting'::text, 'upgrade_checking'::text]))) AND (NOT record ? 'action_consents'::text OR NOT record ? 'action_consent'::text AND deft_app_connection_actions_v2_valid(record -> 'action_consents'::text, record -> 'scope'::text)) AND (NOT record ? 'upgrade'::text OR NOT record ? 'reattachment'::text AND record ? 'action_consents'::text AND deft_app_connection_upgrade_valid(record -> 'upgrade'::text, record -> 'scope'::text)) AND deft_app_connection_reattachment_valid(record -> 'reattachment'::text, record -> 'scope'::text) AND (NOT record ? 'reattachment'::text OR ((record ->> 'state'::text) <> ALL (ARRAY['awaiting_callback'::text, 'connecting'::text]))) AND (NOT record ? 'restore'::text OR (jsonb_typeof(record -> 'restore'::text) = 'object'::text AND (record -> 'restore'::text) ?& ARRAY['schema_version'::text, 'source'::text] AND ((record -> 'restore'::text) - ARRAY['schema_version'::text, 'source'::text]) = '{}'::jsonb AND (record -> 'restore'::text ->> 'schema_version'::text) = 'deft.app_connection_restore.v1' AND jsonb_typeof((record -> 'restore'::text) -> 'source'::text) = 'object'::text AND ((record -> 'restore'::text) -> 'source'::text) ?& ARRAY['session_id'::text] AND (((record -> 'restore'::text) -> 'source'::text) - ARRAY['session_id'::text]) = '{}'::jsonb AND (((record -> 'restore'::text) -> 'source'::text) ->> 'session_id'::text) ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'::text AND (((record -> 'restore'::text) -> 'source'::text) ->> 'session_id'::text) <> session_id))) IS TRUE
END);

CREATE OR REPLACE FUNCTION public.deft_app_connection_credential_repair_record_valid(r jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE u jsonb:=r->'credential_repair'; s text:=r->>'state'; p jsonb:=r->'profile'; n numeric; k text;
BEGIN
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR NOT r ?& ARRAY['session_id','revision','scope','profile','state','callback_state_hash','callback_consumed','callback_expires_at','runtime_session_ref','account','created_at','updated_at','action_consents','credential_repair']
 OR r-ARRAY['session_id','revision','scope','profile','state','callback_state_hash','callback_consumed','callback_expires_at','runtime_session_ref','account','created_at','updated_at','action_consents','credential_repair','restore']<>'{}'::jsonb
 OR jsonb_typeof(r->'scope') IS DISTINCT FROM 'object' OR jsonb_typeof(r->'profile') IS DISTINCT FROM 'object'
 OR jsonb_typeof(r->'session_id') IS DISTINCT FROM 'string' OR NOT COALESCE(r->>'session_id' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$',false)
 OR jsonb_typeof(r->'revision') IS DISTINCT FROM 'number' OR jsonb_typeof(r->'state') IS DISTINCT FROM 'string'
 OR NOT COALESCE(public.deft_app_connection_form_scope_valid(r->'scope'),false)
 OR NOT COALESCE(public.deft_app_connection_credential_repair_valid(u,r->'scope'),false)
 OR NOT COALESCE(public.deft_app_connection_actions_v2_valid(r->'action_consents',r->'scope'),false)
 OR NOT COALESCE(r->>'callback_state_hash' ~ '^[a-f0-9]{64}$',false) OR jsonb_typeof(r->'callback_consumed') IS DISTINCT FROM 'boolean'
 OR NOT isfinite((r->>'callback_expires_at')::timestamptz) OR (r->>'callback_expires_at')::timestamptz>deft_app_consent_deadline(r->'scope')
 OR NOT isfinite((r->>'created_at')::timestamptz) OR NOT isfinite((r->>'updated_at')::timestamptz) OR (r->>'updated_at')::timestamptz<(r->>'created_at')::timestamptz
 OR u->'source'->>'session_id'=r->>'session_id' OR u->'review'->'fence'->>'repair_session_id' IS DISTINCT FROM (CASE WHEN u->'review'='null'::jsonb THEN NULL ELSE r->>'session_id' END) THEN RETURN false; END IF;
 n:=(r->>'revision')::numeric; IF n<>trunc(n) OR n NOT BETWEEN 0 AND 2147483647 THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['created_at','updated_at','callback_expires_at'] LOOP IF jsonb_typeof(r->k) IS DISTINCT FROM 'string' THEN RETURN false; END IF; END LOOP;
 IF NOT p ?& ARRAY['schema_version','key','provider_id','operator_user_id','runtime_requirement_key','resource_key','action_keys','authorization_origin','credential_custody','executable']
 OR p-ARRAY['schema_version','key','provider_id','operator_user_id','runtime_requirement_key','resource_key','action_keys','authorization_origin','credential_custody','executable']<>'{}'::jsonb
 OR p->>'schema_version' IS DISTINCT FROM 'deft.app_connection_profile.v1' OR p->>'credential_custody' IS DISTINCT FROM 'runtime' OR p->'executable' IS DISTINCT FROM 'false'::jsonb
 OR p->'operator_user_id' IS DISTINCT FROM r->'scope'->'operator_user_id' OR p->'resource_key' IS DISTINCT FROM r->'scope'->'resource_key'
 OR jsonb_typeof(p->'authorization_origin') IS DISTINCT FROM 'string' OR NOT COALESCE(p->>'authorization_origin' ~ '^https://[^/?#@]+$',false) OR length(p->>'authorization_origin')>512
 OR jsonb_typeof(p->'action_keys') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'action_keys')>16 THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['key','provider_id','runtime_requirement_key','resource_key'] LOOP IF jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR NOT COALESCE(p->>k ~ '^[a-z][a-z0-9_]{0,47}$',false) OR p->>k IN ('constructor','prototype','__proto__') THEN RETURN false; END IF; END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'action_keys') a WHERE jsonb_typeof(a) IS DISTINCT FROM 'string' OR NOT COALESCE(a#>>'{}' ~ '^[a-z][a-z0-9_]{0,47}$',false) OR a#>>'{}' IN ('constructor','prototype','__proto__')) THEN RETURN false; END IF;
 IF u ? 'closure' THEN
  IF u->'closure'->>'reason'='intent_cancelled' THEN RETURN COALESCE(r->'account'='null'::jsonb AND r->'runtime_session_ref'='null'::jsonb
   AND r->'callback_consumed'='false'::jsonb AND s IN ('not_connected','repair_checking','indeterminate')
   AND u->'closure'->'intent_fence'->>'repair_session_id'=r->>'session_id',false); END IF;
  RETURN COALESCE(r->'account'='null'::jsonb AND s IN ('not_connected','repair_checking','indeterminate') AND
   CASE u->'closure'->>'reason' WHEN 'prepared_cancelled' THEN r->'callback_consumed'='false'::jsonb
    WHEN 'callback_expired' THEN r->'callback_consumed'='false'::jsonb AND (r->>'callback_expires_at')::timestamptz<=(r->>'updated_at')::timestamptz
    WHEN 'exchange_abandoned' THEN r->'callback_consumed'='true'::jsonb AND r->'runtime_session_ref'<>'null'::jsonb AND (u->>'review_expires_at')::timestamptz<=(r->>'updated_at')::timestamptz
    WHEN 'provider_denied' THEN r->'callback_consumed'='true'::jsonb ELSE false END,false);
 END IF;
 IF u->'receipt'<>'null'::jsonb THEN RETURN COALESCE(r->'callback_consumed'='true'::jsonb AND (r->'account'='null'::jsonb OR r->'account'=u->'review'->'account')
  AND (s<>'connected' OR r->'account'=u->'review'->'account')
  AND r->'runtime_session_ref'<>'null'::jsonb AND s IN ('connected','repair_checking','checking','disconnecting','disconnected','indeterminate'),false); END IF;
 IF r->'account'<>'null'::jsonb THEN RETURN false; END IF;
 IF s='repair_reviewed' THEN RETURN COALESCE(u->'review'<>'null'::jsonb AND u->'begin_consumed'='false'::jsonb AND r->'callback_consumed'='false'::jsonb,false); END IF;
 IF s='repair_starting' THEN RETURN COALESCE(u->'begin_consumed'='true'::jsonb AND r->'callback_consumed'='false'::jsonb,false); END IF;
 IF s='awaiting_callback' THEN RETURN COALESCE(u->'begin_consumed'='true'::jsonb AND r->'runtime_session_ref'<>'null'::jsonb AND r->'callback_consumed'='false'::jsonb,false); END IF;
 IF s='connecting' THEN RETURN COALESCE(u->'begin_consumed'='true'::jsonb AND r->'callback_consumed'='true'::jsonb,false); END IF;
 RETURN COALESCE(s IN ('starting','repair_checking','indeterminate','not_connected'),false);
EXCEPTION WHEN OTHERS THEN RETURN false; END; $function$;
